_64BIT_DTYPES = (torch.float64, torch.complex128)

# Opaqueness scalar: multiplied into every renormalization operand.  It is a
# runtime kernel argument, so the backend's fast-math pass cannot fold it away,
# yet x * 1.0 is bit-exact for every finite x.
_ONE = 1.0


def _prep(t):
    """Return (ptr_tensor, shape, strides) for kernel addressing.

    64-bit dtypes are stored as packed float32 words on this backend, so a
    zero-copy float32 view is used only as the pointer carrier; the returned
    shape/strides are the ORIGINAL tensor's (already word offsets), so the
    addressing frame stays in the caller's dimension order.
    """
    if t.dtype in _64BIT_DTYPES:
        tp = t
        if tp.dim() == 0:
            tp = tp.unsqueeze(0)
        elif tp.stride(-1) != 1:
            st = tp.stride()
            cand = [i for i in range(tp.dim()) if st[i] == 1]
            if not cand:
                raise RuntimeError(
                    "float_power: unsupported 64-bit layout (no unit-stride axis)"
                )
            idx = max(cand, key=lambda i: tp.shape[i])
            perm = [i for i in range(tp.dim()) if i != idx] + [idx]
            tp = tp.permute(perm)
        return tp.view(torch.float32), t.shape, t.stride()
    return t, t.shape, t.stride()


def _broadcast_strides(shape, strides, out_shape):
    ndim = len(out_shape)
    pad = ndim - len(shape)
    res = [0] * ndim
    for i in range(ndim):
        j = i - pad
        if j < 0:
            res[i] = 0
        elif shape[j] == 1 and out_shape[i] != 1:
            res[i] = 0
        else:
            res[i] = strides[j]
    return res


def _pad8(seq, fill=1):
    seq = list(seq)
    return seq + [fill] * (8 - len(seq))


